"use client";

import { useEffect, useState } from "react";
import { apiGet } from "@/lib/api-client";
import { useAppStore } from "@/store/app-store";
import { PageHeader } from "@/components/app/page-header";
import { StatusBadge } from "@/components/app/status-badge";
import { EmptyState, LoadingState, ErrorState } from "@/components/app/empty-state";
import { Card, CardContent } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Truck, Search, MapPin, Calendar, ChevronRight, Heart, Package } from "lucide-react";
import { formatDate, formatDateTime } from "@/lib/constants";

export function TripList() {
  const { navigate, user } = useAppStore();
  const [trips, setTrips] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [search, setSearch] = useState("");

  useEffect(() => {
    (async () => {
      try { const d = await apiGet("/trips"); setTrips(d.trips); }
      catch (e: any) { setError(e.message); }
      finally { setLoading(false); }
    })();
  }, []);

  if (loading) return <LoadingState />;
  if (error) return <ErrorState message={error} />;

  const filtered = trips.filter((t) => !search || (t.request?.competitionName || "").toLowerCase().includes(search.toLowerCase()));

  return (
    <div className="space-y-6">
      <PageHeader
        title={user?.roleId === "DRIVER_ESCORT" ? "Chuyến được giao" : "Chuyến vận chuyển"}
        description="Theo dõi và cập nhật tiến độ chuyến vận chuyển"
        icon={<Truck className="h-5 w-5" />}
        actions={<div className="relative w-full sm:w-64"><Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" /><Input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Tìm chuyến..." className="pl-9" /></div>}
      />
      {filtered.length === 0 ? (
        <EmptyState icon={<Truck className="h-6 w-6" />} title="Chưa có chuyến nào" description="Chuyến vận chuyển sẽ hiển thị tại đây." />
      ) : (
        <div className="space-y-3">
          {filtered.map((t) => (
            <button key={t.planId} onClick={() => navigate("trip-detail", { id: t.planId })} className="flex w-full items-center gap-4 rounded-xl border border-border bg-card p-4 text-left transition-all hover:border-primary/40 hover:shadow-md">
              <div className="flex h-12 w-12 shrink-0 items-center justify-center rounded-xl bg-primary/10 text-primary"><Truck className="h-6 w-6" /></div>
              <div className="min-w-0 flex-1">
                <p className="truncate text-sm font-semibold">{t.request?.competitionName || `Chuyến #${t.planId.slice(-8)}`}</p>
                <div className="mt-1 flex flex-wrap items-center gap-x-4 gap-y-1 text-xs text-muted-foreground">
                  <span className="flex items-center gap-1"><MapPin className="h-3 w-3" />{t.request?.origin?.name} → {t.request?.destination?.name}</span>
                  <span className="flex items-center gap-1"><Calendar className="h-3 w-3" />{formatDateTime(t.departureTime)}</span>
                  <span className="flex items-center gap-1"><Heart className="h-3 w-3" />{t.request?.horses?.length || 0} ngựa</span>
                  {t.assignments?.length > 0 && <span className="flex items-center gap-1"><Package className="h-3 w-3" />{t.assignments.length} phương tiện</span>}
                </div>
              </div>
              <StatusBadge status={t.status} />
              <ChevronRight className="h-4 w-4 text-muted-foreground" />
            </button>
          ))}
        </div>
      )}
    </div>
  );
}
