"use client";

import { useEffect, useState } from "react";
import { apiGet, apiPost } from "@/lib/api-client";
import { useAppStore } from "@/store/app-store";
import { useToast } from "@/hooks/use-toast";
import { PageHeader } from "@/components/app/page-header";
import { EmptyState, LoadingState, ErrorState } from "@/components/app/empty-state";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Bell, CheckCircle2, ChevronRight, MapPin } from "lucide-react";
import { formatDateTime } from "@/lib/constants";

export function NotificationsView() {
  const { navigate } = useAppStore();
  const { toast } = useToast();
  const [notifications, setNotifications] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  const load = async () => {
    try { const d = await apiGet("/notifications"); setNotifications(d.notifications); }
    catch (e: any) { setError(e.message); }
    finally { setLoading(false); }
  };

  useEffect(() => { load(); }, []);

  const handleMarkRead = async (id: string) => {
    try {
      await apiPost("/notifications", { notificationId: id });
      load();
    } catch (e: any) { toast({ title: "Lỗi", description: e.message, variant: "destructive" }); }
  };

  const handleClick = (n: any) => {
    if (!n.isRead) handleMarkRead(n.notificationId);
    if (n.relatedEntityType === "transport_requests") navigate("request-detail", { id: n.relatedEntityId });
    else if (n.relatedEntityType === "transport_plans") navigate("trip-detail", { id: n.relatedEntityId });
  };

  if (loading) return <LoadingState />;
  if (error) return <ErrorState message={error} />;

  return (
    <div className="space-y-6">
      <PageHeader title="Thông báo" description="Tất cả thông báo và cảnh báo hệ thống" icon={<Bell className="h-5 w-5" />} />
      {notifications.length === 0 ? <EmptyState illustration="no-data" title="Không có thông báo" /> : (
        <div className="space-y-2">
          {notifications.map((n) => (
            <button key={n.notificationId} onClick={() => handleClick(n)} className={`flex w-full items-start gap-4 rounded-xl border p-4 text-left transition-all hover:shadow-sm ${n.isSos || n.type === "INCIDENT_SOS" ? "border-[var(--danger)]/30 bg-[var(--danger-bg)]/40" : n.isRead ? "border-border bg-card" : "border-primary/30 bg-primary/5"}`}>
              <div className={`mt-0.5 flex h-9 w-9 shrink-0 items-center justify-center rounded-lg ${n.type === "INCIDENT_SOS" ? "bg-[var(--danger)] text-white" : n.isRead ? "bg-muted text-muted-foreground" : "bg-primary text-primary-foreground"}`}>
                {n.type === "INCIDENT_SOS" ? <Bell className="h-4 w-4" /> : n.isRead ? <CheckCircle2 className="h-4 w-4" /> : <Bell className="h-4 w-4" />}
              </div>
              <div className="min-w-0 flex-1">
                <div className="flex items-center justify-between gap-2">
                  <p className={`text-sm ${n.isRead ? "font-medium" : "font-bold"}`}>{n.title}</p>
                  {!n.isRead && <span className="h-2 w-2 shrink-0 rounded-full bg-primary" />}
                </div>
                <p className="mt-0.5 text-xs text-muted-foreground line-clamp-2">{n.message}</p>
                <p className="mt-1 text-[10px] text-muted-foreground">{formatDateTime(n.createdAt)}</p>
              </div>
              <ChevronRight className="h-4 w-4 shrink-0 text-muted-foreground" />
            </button>
          ))}
        </div>
      )}
    </div>
  );
}
