"use client";

import { useEffect, useState, useCallback } from "react";
import { apiGet, apiPost } from "@/lib/api-client";
import { useAppStore } from "@/store/app-store";
import { useToast } from "@/hooks/use-toast";
import { PageHeader } from "@/components/app/page-header";
import { StatusBadge } from "@/components/app/status-badge";
import { LoadingState, ErrorState } from "@/components/app/empty-state";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import { ArrowLeft, Receipt, MapPin, Calendar, CreditCard, CheckCircle2, Plus, Download, FileText, User, Printer } from "lucide-react";
import { formatDate, formatDateTime, formatMoney } from "@/lib/constants";
import { exportToCSV } from "@/lib/csv-export";

export function InvoiceDetail() {
  const { params, navigate, user } = useAppStore();
  const { toast } = useToast();
  const [invoice, setInvoice] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [actionLoading, setActionLoading] = useState(false);
  const [showPayForm, setShowPayForm] = useState(false);
  const [payForm, setPayForm] = useState({ amount: "", method: "Chuyển khoản", reference: "", notes: "" });

  const load = useCallback(async () => {
    try { const d = await apiGet(`/invoices/${params.id}`); setInvoice(d.invoice); setPayForm((f) => ({ ...f, amount: String(d.invoice.amount - (d.invoice.payments?.filter((p:any) => p.status === "Thành công").reduce((s:number, p:any) => s + p.amount, 0) || 0)) })); }
    catch (e: any) { setError(e.message); }
    finally { setLoading(false); }
  }, [params.id]);

  useEffect(() => { load(); }, [load]);

  const handlePay = async () => {
    if (!payForm.amount || Number(payForm.amount) <= 0) { toast({ title: "Nhập số tiền hợp lệ", variant: "destructive" }); return; }
    setActionLoading(true);
    try {
      const res = await apiPost(`/invoices/${params.id}/payments`, payForm);
      toast({ title: "Đã ghi nhận thanh toán", description: `Trạng thái: ${res.newStatus}` });
      setShowPayForm(false);
      setPayForm({ amount: "", method: "Chuyển khoản", reference: "", notes: "" });
      load();
    } catch (e: any) { toast({ title: "Lỗi", description: e.message, variant: "destructive" }); }
    finally { setActionLoading(false); }
  };

  if (loading) return <LoadingState />;
  if (error) return <ErrorState message={error} />;
  if (!invoice) return <ErrorState message="Không tìm thấy hóa đơn" />;

  const totalPaid = (invoice.payments || []).filter((p: any) => p.status === "Thành công").reduce((s: number, p: any) => s + p.amount, 0);
  const remaining = invoice.amount - totalPaid;
  const isManager = user?.roleId === "LOGISTICS_MANAGER";
  const isCustomer = user?.roleId === "CUSTOMER";
  const canPay = (isCustomer || isManager) && remaining > 0 && invoice.paymentStatus !== "Đã thanh toán";

  return (
    <div className="space-y-6">
      <PageHeader
        title={`Hóa đơn #${invoice.invoiceId.slice(-8).toUpperCase()}`}
        description={invoice.request?.competitionName || "Hóa đơn vận chuyển"}
        icon={<Receipt className="h-5 w-5" />}
        actions={
          <div className="no-print flex items-center gap-2">
            <StatusBadge status={invoice.paymentStatus} />
            <Button variant="outline" size="sm" onClick={() => window.print()} className="gap-2"><Printer className="h-4 w-4" /> <span className="hidden sm:inline">In</span></Button>
            <Button variant="outline" size="sm" onClick={() => navigate("invoices")} className="gap-2"><ArrowLeft className="h-4 w-4" /> Quay lại</Button>
          </div>
        }
      />

      {/* Printable invoice header */}
      <div className="print-area">
        <div className="mb-4 hidden print:block">
          <div className="flex items-center justify-between border-b-2 border-[var(--chestnut)] pb-3">
            <div className="flex items-center gap-3">
              <img src="/equideli-logo.png" alt="EQUIDELI" className="h-12 w-12 rounded-lg" />
              <div>
                <p className="text-2xl font-extrabold text-[var(--chestnut)]">EQUIDELI</p>
                <p className="text-xs text-[var(--ink-soft)]">Hệ thống quản lý vận chuyển ngựa đua</p>
              </div>
            </div>
            <div className="text-right">
              <p className="text-lg font-bold">HÓA ĐƠN</p>
              <p className="text-xs">#{invoice.invoiceId.slice(-8).toUpperCase()}</p>
              <p className="text-xs">{formatDate(invoice.issuedAt)}</p>
            </div>
          </div>
        </div>
      </div>

      <div className="grid gap-6 lg:grid-cols-3">
        {/* Main invoice info */}
        <div className="space-y-6 lg:col-span-2">
          <Card>
            <CardHeader><CardTitle className="text-base flex items-center gap-2"><FileText className="h-4 w-4" /> Chi tiết hóa đơn</CardTitle></CardHeader>
            <CardContent className="space-y-3 text-sm">
              <div className="grid gap-3 sm:grid-cols-2">
                <div><p className="text-xs text-muted-foreground">Mã hóa đơn</p><p className="font-mono text-xs font-medium">{invoice.invoiceId}</p></div>
                <div><p className="text-xs text-muted-foreground">Ngày phát hành</p><p className="font-medium">{formatDateTime(invoice.issuedAt)}</p></div>
                <div><p className="text-xs text-muted-foreground">Hạn thanh toán</p><p className="font-medium">{formatDate(invoice.dueDate)}</p></div>
                <div><p className="text-xs text-muted-foreground">Phương thức</p><p className="font-medium">{invoice.paymentMethod || "—"}</p></div>
              </div>
              <div className="border-t border-border pt-3">
                <p className="text-xs text-muted-foreground">Đơn vận chuyển liên quan</p>
                <button onClick={() => navigate("request-detail", { id: invoice.requestId })} className="mt-1 text-sm font-semibold text-primary hover:underline">{invoice.request?.competitionName}</button>
                <div className="mt-1 flex items-center gap-2 text-xs text-muted-foreground"><MapPin className="h-3 w-3" />{invoice.request?.origin?.name} → {invoice.request?.destination?.name}</div>
              </div>
              {invoice.notes && <div className="border-t border-border pt-3"><p className="text-xs text-muted-foreground">Ghi chú</p><p className="mt-1 text-sm">{invoice.notes}</p></div>}
            </CardContent>
          </Card>

          {/* Payment breakdown */}
          <Card>
            <CardHeader><CardTitle className="text-base flex items-center gap-2"><CreditCard className="h-4 w-4" /> Thanh toán</CardTitle></CardHeader>
            <CardContent className="space-y-4">
              <div className="grid gap-3 sm:grid-cols-3">
                <div className="rounded-lg bg-muted/50 p-3"><p className="text-xs text-muted-foreground">Tổng hóa đơn</p><p className="text-lg font-bold">{formatMoney(invoice.amount, invoice.currency)}</p></div>
                <div className="rounded-lg bg-[var(--success-bg)]/40 p-3"><p className="text-xs text-muted-foreground">Đã trả</p><p className="text-lg font-bold text-[var(--success-fg)]">{formatMoney(totalPaid, invoice.currency)}</p></div>
                <div className="rounded-lg bg-[var(--warning-bg)]/40 p-3"><p className="text-xs text-muted-foreground">Còn lại</p><p className="text-lg font-bold text-[var(--warning-fg)]">{formatMoney(remaining, invoice.currency)}</p></div>
              </div>

              {/* Payment history */}
              {invoice.payments?.length > 0 && (
                <div>
                  <p className="mb-2 text-xs font-medium uppercase tracking-wider text-muted-foreground">Lịch sử thanh toán</p>
                  <div className="space-y-2">
                    {invoice.payments.map((p: any) => (
                      <div key={p.transactionId} className="flex items-center justify-between gap-3 rounded-lg border border-border p-3">
                        <div className="flex items-center gap-3">
                          <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-[var(--success-bg)] text-[var(--success-fg)]"><CheckCircle2 className="h-4 w-4" /></div>
                          <div>
                            <p className="text-sm font-medium">{p.method}</p>
                            <p className="text-xs text-muted-foreground">{formatDateTime(p.processedAt)}{p.reference ? ` · Mã: ${p.reference}` : ""}</p>
                          </div>
                        </div>
                        <div className="text-right"><p className="text-sm font-bold text-[var(--success-fg)]">{formatMoney(p.amount, invoice.currency)}</p><StatusBadge status={p.status} /></div>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {/* Pay button / form */}
              {canPay ? (
                !showPayForm ? (
                  <Button onClick={() => setShowPayForm(true)} className="w-full gap-2 bg-[var(--success)] hover:bg-[var(--success)]/90"><CreditCard className="h-4 w-4" /> {isCustomer ? "Thanh toán hóa đơn" : "Ghi nhận thanh toán"}</Button>
                ) : (
                  <Card className="border-primary/30 bg-primary/5">
                    <CardContent className="space-y-3 p-4">
                      <div className="grid gap-3 sm:grid-cols-2">
                        <div className="space-y-2"><Label className="text-xs">Số tiền</Label><Input type="number" value={payForm.amount} onChange={(e) => setPayForm({ ...payForm, amount: e.target.value })} placeholder={String(remaining)} /></div>
                        <div className="space-y-2"><Label className="text-xs">Phương thức</Label><select value={payForm.method} onChange={(e) => setPayForm({ ...payForm, method: e.target.value })} className="flex h-10 w-full rounded-md border border-input bg-background px-3 text-sm"><option>Chuyển khoản</option><option>Tiền mặt</option><option>Thẻ tín dụng</option></select></div>
                      </div>
                      <div className="space-y-2"><Label className="text-xs">Mã giao dịch (tùy chọn)</Label><Input value={payForm.reference} onChange={(e) => setPayForm({ ...payForm, reference: e.target.value })} placeholder="VD: TXN-2026-001" /></div>
                      <div className="space-y-2"><Label className="text-xs">Ghi chú</Label><Textarea value={payForm.notes} onChange={(e) => setPayForm({ ...payForm, notes: e.target.value })} rows={2} /></div>
                      <div className="flex gap-2">
                        <Button onClick={handlePay} disabled={actionLoading} className="flex-1 gap-2 bg-[var(--success)] hover:bg-[var(--success)]/90"><CheckCircle2 className="h-4 w-4" /> Xác nhận thanh toán</Button>
                        <Button variant="outline" onClick={() => setShowPayForm(false)}>Hủy</Button>
                      </div>
                    </CardContent>
                  </Card>
                )
              ) : invoice.paymentStatus === "Đã thanh toán" && (
                <div className="rounded-lg border border-[var(--success)]/30 bg-[var(--success-bg)]/30 p-4 text-center">
                  <CheckCircle2 className="mx-auto h-8 w-8 text-[var(--success)]" />
                  <p className="mt-2 font-semibold text-[var(--success-fg)]">Hóa đơn đã thanh toán đầy đủ</p>
                  <p className="text-xs text-[var(--success-fg)]/70">Hoàn tất lúc {formatDateTime(invoice.paidAt)}</p>
                </div>
              )}
            </CardContent>
          </Card>
        </div>

        {/* Sidebar */}
        <div className="space-y-6">
          <Card>
            <CardHeader><CardTitle className="text-base flex items-center gap-2"><User className="h-4 w-4" /> Khách hàng</CardTitle></CardHeader>
            <CardContent className="space-y-2 text-sm">
              <div><p className="text-xs text-muted-foreground">Tên</p><p className="font-medium">{invoice.request?.customer?.name}</p></div>
              <div><p className="text-xs text-muted-foreground">Tổ chức</p><p className="font-medium">{invoice.request?.customer?.organizationName || "—"}</p></div>
              <div><p className="text-xs text-muted-foreground">Email</p><p className="font-medium break-all">{invoice.request?.customer?.email}</p></div>
            </CardContent>
          </Card>

          <Card>
            <CardHeader><CardTitle className="text-base">Tóm tắt chi phí</CardTitle></CardHeader>
            <CardContent className="space-y-2 text-sm">
              <div className="flex justify-between"><span className="text-muted-foreground">Tổng hóa đơn</span><span className="font-medium">{formatMoney(invoice.amount, invoice.currency)}</span></div>
              <div className="flex justify-between"><span className="text-muted-foreground">Đã thanh toán</span><span className="font-medium text-[var(--success-fg)]">−{formatMoney(totalPaid, invoice.currency)}</span></div>
              <div className="flex justify-between border-t border-border pt-2 text-base font-bold"><span>Còn phải trả</span><span className="text-[var(--warning-fg)]">{formatMoney(remaining, invoice.currency)}</span></div>
            </CardContent>
          </Card>

          <div className="no-print space-y-2">
            <Button variant="outline" className="w-full gap-2" onClick={() => window.print()}><Printer className="h-4 w-4" /> In / Lưu PDF</Button>
            <Button variant="outline" className="w-full gap-2" onClick={() => {
              exportToCSV(`hoa-don-${invoice.invoiceId.slice(-8)}.csv`,
                ["Mã", "Cuộc thi", "Khách hàng", "Số tiền", "Loại tiền", "Trạng thái", "Hạn", "Ngày phát hành"],
                [[invoice.invoiceId.slice(-8).toUpperCase(), invoice.request?.competitionName || "", invoice.request?.customer?.name || "", invoice.amount, invoice.currency, invoice.paymentStatus, formatDate(invoice.dueDate), formatDate(invoice.issuedAt)]]);
              toast({ title: "Đã xuất CSV" });
            }}><Download className="h-4 w-4" /> Tải CSV</Button>
          </div>
        </div>
      </div>

      {/* Print footer */}
      <div className="hidden print:block mt-8 border-t border-[var(--ink-soft)] pt-3 text-center text-xs text-[var(--ink-soft)]">
        <p>Cảm ơn quý khách đã sử dụng dịch vụ vận chuyển ngựa đua EQUIDELI.</p>
        <p className="mt-1">EQUIDELI © 2026 · Hệ thống quản lý vận chuyển ngựa đua xuyên biên giới</p>
      </div>
    </div>
  );
}
